1	/* ===========================================
2	   VIEWPORT FITTING: MANDATORY BASE STYLES
3	   Include this ENTIRE file in every presentation.
4	   These styles ensure slides fit exactly in the viewport.
5	   =========================================== */
6	
7	/* 1. Lock html/body to viewport */
8	html, body {
9	    height: 100%;
10	    overflow-x: hidden;
11	}
12	
13	html {
14	    scroll-snap-type: y mandatory;
15	    scroll-behavior: smooth;
16	}
17	
18	/* 2. Each slide = exact viewport height */
19	.slide {
20	    width: 100vw;
21	    height: 100vh;
22	    height: 100dvh; /* Dynamic viewport height for mobile browsers */
23	    overflow: hidden; /* CRITICAL: Prevent ANY overflow */
24	    scroll-snap-align: start;
25	    display: flex;
26	    flex-direction: column;
27	    position: relative;
28	}
29	
30	/* 3. Content container with flex for centering */
31	.slide-content {
32	    flex: 1;
33	    display: flex;
34	    flex-direction: column;
35	    justify-content: center;
36	    max-height: 100%;
37	    overflow: hidden; /* Double-protection against overflow */
38	    padding: var(--slide-padding);
39	}
40	
41	/* 4. ALL typography uses clamp() for responsive scaling */
42	:root {
43	    /* Titles scale from mobile to desktop */
44	    --title-size: clamp(1.5rem, 5vw, 4rem);
45	    --h2-size: clamp(1.25rem, 3.5vw, 2.5rem);
46	    --h3-size: clamp(1rem, 2.5vw, 1.75rem);
47	
48	    /* Body text */
49	    --body-size: clamp(0.75rem, 1.5vw, 1.125rem);
50	    --small-size: clamp(0.65rem, 1vw, 0.875rem);
51	
52	    /* Spacing scales with viewport */
53	    --slide-padding: clamp(1rem, 4vw, 4rem);
54	    --content-gap: clamp(0.5rem, 2vw, 2rem);
55	    --element-gap: clamp(0.25rem, 1vw, 1rem);
56	}
57	
58	/* 5. Cards/containers use viewport-relative max sizes */
59	.card, .container, .content-box {
60	    max-width: min(90vw, 1000px);
61	    max-height: min(80vh, 700px);
62	}
63	
64	/* 6. Lists auto-scale with viewport */
65	.feature-list, .bullet-list {
66	    gap: clamp(0.4rem, 1vh, 1rem);
67	}
68	
69	.feature-list li, .bullet-list li {
70	    font-size: var(--body-size);
71	    line-height: 1.4;
72	}
73	
74	/* 7. Grids adapt to available space */
75	.grid {
76	    display: grid;
77	    grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
78	    gap: clamp(0.5rem, 1.5vw, 1rem);
79	}
80	
81	/* 8. Images constrained to viewport */
82	img, .image-container {
83	    max-width: 100%;
84	    max-height: min(50vh, 400px);
85	    object-fit: contain;
86	}
87	
88	/* ===========================================
89	   RESPONSIVE BREAKPOINTS
90	   Aggressive scaling for smaller viewports
91	   =========================================== */
92	
93	/* Short viewports (< 700px height) */
94	@media (max-height: 700px) {
95	    :root {
96	        --slide-padding: clamp(0.75rem, 3vw, 2rem);
97	        --content-gap: clamp(0.4rem, 1.5vw, 1rem);
98	        --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
99	        --h2-size: clamp(1rem, 3vw, 1.75rem);
100	    }
101	}
102	
103	/* Very short viewports (< 600px height) */
104	@media (max-height: 600px) {
105	    :root {
106	        --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
107	        --content-gap: clamp(0.3rem, 1vw, 0.75rem);
108	        --title-size: clamp(1.1rem, 4vw, 2rem);
109	        --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
110	    }
111	
112	    /* Hide non-essential elements */
113	    .nav-dots, .keyboard-hint, .decorative {
114	        display: none;
115	    }
116	}
117	
118	/* Extremely short (landscape phones, < 500px height) */
119	@media (max-height: 500px) {
120	    :root {
121	        --slide-padding: clamp(0.4rem, 2vw, 1rem);
122	        --title-size: clamp(1rem, 3.5vw, 1.5rem);
123	        --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
124	        --body-size: clamp(0.65rem, 1vw, 0.85rem);
125	    }
126	}
127	
128	/* Narrow viewports (< 600px width) */
129	@media (max-width: 600px) {
130	    :root {
131	        --title-size: clamp(1.25rem, 7vw, 2.5rem);
132	    }
133	
134	    /* Stack grids vertically */
135	    .grid {
136	        grid-template-columns: 1fr;
137	    }
138	}
139	
140	/* ===========================================
141	   REDUCED MOTION
142	   Respect user preferences
143	   =========================================== */
144	@media (prefers-reduced-motion: reduce) {
145	    *, *::before, *::after {
146	        animation-duration: 0.01ms !important;
147	        transition-duration: 0.2s !important;
148	    }
149	
150	    html {
151	        scroll-behavior: auto;
152	    }
153	}
