            background: rgba(255,255,255,0.2);
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .nav-dot.active {
            background: var(--accent-gold);
            transform: scale(1.3);
        }

        .nav-dot:hover {
            background: rgba(255,255,255,0.4);
        }

        /* Progress bar */
        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 3px;
            background: linear-gradient(90deg, var(--accent-gold), var(--accent-warm));
            z-index: 101;
            transition: width 0.3s ease;
        }

        /* Keyboard hint */
        .keyboard-hint {
            position: fixed;
            bottom: clamp(1rem, 2vw, 2rem);
            left: 50%;
            transform: translateX(-50%);
            font-size: clamp(0.55rem, 0.9vw, 0.7rem);
            color: var(--text-secondary);
            opacity: 0.4;
        }

        /* Two column layout */
        .two-col {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1.5rem, 4vw, 4rem);
            align-items: start;
        }

        @media (max-width: 700px) {
            .two-col, .comparison-table, .region-visual {
                grid-template-columns: 1fr;
            }
            .bar-row {
                grid-template-columns: clamp(60px, 12vw, 100px) 1fr clamp(40px, 8vw, 70px);
            }
        }

        /* Bullet list styling */
        .bullet-list {
            list-style: none;
            padding: 0;
        }

        .bullet-list li {
            position: relative;
            padding-left: clamp(1rem, 2vw, 1.5rem);
            margin-bottom: var(--element-gap);
        }

        .bullet-list li::before {
            content: '';
            position: absolute;
            left: 0;
            top: 0.6em;
            width: 6px;
            height: 6px;
            background: var(--accent-gold);
            border-radius: 50%;
        }

        /* Grid of stat cards */
        .stat-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(45%, 200px), 1fr));
            gap: clamp(0.8rem, 2vw, 1.5rem);
        }

        .stat-card {
            background: rgba(255,255,255,0.03);
            border-radius: 8px;
            padding: clamp(0.8rem, 2vw, 1.2rem);
            text-align: center;
        }

        .stat-card .value {
            font-family: var(--font-display);
            font-size: clamp(1.5rem, 4vw, 2.5rem);
            font-weight: 700;
            color: var(--accent-gold);
        }

        .stat-card .label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 0.3em;
        }

        /* Inline image styling */
        .slide-image {
            max-height: min(40vh, 320px);
            border-radius: 8px;
            box-shadow: 0 8px 32px rgba(0,0,0,0.3);
        }
    </style>
</head>
<body>
    <!-- Progress bar -->
